def summarize_chip_yield(rows, required_items):
    chips = {}
    duplicates_ignored = 0
    missing_values = 0

    for row in rows:
        chip_id = row["chip_id"]
        test_item = row["test_item"]
        value = row["value"]
        unit = row["unit"]
        lower = row["lower"]
        upper = row["upper"]
        retest = row["retest"]

        if unit not in ("V", "mV"):  # Check unit
            raise ValueError(f'Invalid unit: {unit}')

        if unit == "mV":
            value = float(value) / 1000
            lower = float(lower) / 1000
            upper = float(upper) / 1000

        try:
            value = float(value)
            lower = float(lower)
            upper = float(upper)
            retest = int(retest)
        except ValueError:
            raise ValueError(f'Invalid value for row: {row}')

        key = (chip_id, test_item, retest)
        if key in chips:
            if chips[key][2] != retest:
                raise ValueError(f'Conflicting rows for key: {key}
Row 1: {chips[key][0]}
Row 2: {row}')
            if value != chips[key][1]:
                raise ValueError(f'Conflicting values for key: {key}
Row 1: {chips[key][1]}
Row 2: {value}')
        else:
            chips[key] = (row, value, retest)

    passed_chips = 0
    for chip_id, test_item in required_items:
        key = (chip_id, test_item, 0)
        if key in chips:
            if chips[key][1] >= chips[key][0]["lower"] and chips[key][1] <= chips[key][0]["upper"]:
                passed_chips += 1
        else:
            missing_values += 1

    yield {
        "chips": len(chips),
        "passed_chips": passed_chips,
        "yield": passed_chips / len(chips) if len(chips) > 0 else 0,
        "failed_chip_ids": [chip_id for chip_id, test_item in required_items if (chip_id, test_item, 0) not in chips],
        "duplicates_ignored": duplicates_ignored,
        "missing_values": missing_values
    }
